), upd as (
  update public.shift_templates t set grp=v.grp, start_time=v.start_time, end_time=v.end_time, color=v.color,
         lots=v.lots, checklist=v.checklist, notes=v.notes, unpaid_break=v.unpaid_break, active=v.active
    from v where t.name = v.name
  returning t.name
)
insert into public.shift_templates(name,grp,start_time,end_time,color,lots,checklist,notes,unpaid_break,active)
  select * from v where v.name not in (select name from public.shift_templates);
select name, cardinality(checklist) as checklist_items, cardinality(lots) as route_lots
  from public.shift_templates where grp = 'Parking Events/Enforcement' order by name;
